    def _parse_hhmm(hhmm: str) -> Optional[tuple[int, int]]:
        s = (hhmm or "").strip()
        if not s:
            return None
        if ":" not in s:
            return None
        a, b = s.split(":", 1)
        try:
            hh = int(a)
            mm = int(b)
        except Exception:
            return None
        if not (0 <= hh <= 23 and 0 <= mm <= 59):
            return None
        return (hh, mm)

